import FreeCAD
import Part

doc = FreeCAD.newDocument("TransformerBobbin")

# Cylindrical barrel
outer_barrel = Part.makeCylinder(9.5, 25.0)
inner_hole = Part.makeCylinder(8.0, 25.0)
barrel = outer_barrel.cut(inner_hole)

# Flanges
bottom_flange = Part.makeCylinder(16.0, 1.5)
bottom_flange_hole = Part.makeCylinder(8.0, 1.5)
bottom = bottom_flange.cut(bottom_flange_hole)

top_flange = Part.makeCylinder(16.0, 1.5)
top_flange.translate(FreeCAD.Vector(0, 0, 23.5))
top_flange_hole = Part.makeCylinder(8.0, 1.5)
top_flange_hole.translate(FreeCAD.Vector(0, 0, 23.5))
top = top_flange.cut(top_flange_hole)

# Fuse bobbin assembly
bobbin = barrel.fuse(bottom).fuse(top)
obj = doc.addObject("Part::Feature", "Bobbin")
obj.Shape = bobbin
doc.recompute()

# Export STEP
Part.export([obj], "C:/Mendex studio/docs/v1.6/evidence/freecad/bobbin.step")
print("STEP export complete: C:/Mendex studio/docs/v1.6/evidence/freecad/bobbin.step")
